# ============================================================
# 018_CorrelationStructure_Permutation.R
#
# Objective 2
# Permutation test for changes in behavioural correlation structure
#
# The analysis compares the complete independent Control and Stress
# populations in the definitive four-dimensional behavioural space
# generated by Script 011 after robust normalisation within Author.
#
# Observed correlations are Spearman correlations. To test changes in
# dependence structure without carrying the already demonstrated group
# differences in marginal location and scale into the null distribution,
# each variable is converted to centred and standardised midrank scores
# within its original treatment group. Pearson correlations of these
# scores reproduce the observed Spearman correlations exactly. The two
# independent-group labels are then permuted on the pooled rank scores.
#
# This population-level analysis does not use Louvain memberships,
# because it compares the correlation structures of the complete
# Control and Stress populations.
# ============================================================

# ------------------------------------------------------------
# 1. Project directory and packages
# ------------------------------------------------------------

project_root <- normalizePath(
  Sys.getenv(
    "LAPCOM_UCS_PROJECT_ROOT",
    unset = getwd()
  ),
  winslash = "/",
  mustWork = TRUE
)

if (!dir.exists(project_root)) {
  stop("Project directory not found:\n", project_root)
}

setwd(project_root)

required_packages <- c("openxlsx")
missing_packages <- required_packages[
  !vapply(required_packages, requireNamespace, logical(1), quietly = TRUE)
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following package(s) before running this script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

# ------------------------------------------------------------
# 2. Fixed settings
# ------------------------------------------------------------

required_treatments <- c("Control", "Stress")
expected_control_n <- 89L
expected_stress_n <- 89L
expected_number_of_authors <- 4L

expected_traceability <- "Author + ID"
expected_normalisation <-
  "Within Author: (x - median) / (1.4826 x raw MAD)"

behavioural_variables <- c(
  "distance",
  "crossing",
  "top_entry",
  "top_time"
)

robust_variables <- paste0(behavioural_variables, "_rz")

variable_labels <- c(
  distance = "Distance travelled",
  crossing = "Line crossings",
  top_entry = "Upper-zone entries",
  top_time = "Upper-zone time"
)

n_permutations <- 9999L
permutation_seed <- 1234L
numeric_tolerance <- 1e-10

if (
  length(n_permutations) != 1L ||
  !is.finite(n_permutations) ||
  n_permutations < 999L ||
  n_permutations != as.integer(n_permutations)
) {
  stop("n_permutations must be a single integer of at least 999.")
}

# ------------------------------------------------------------
# 3. Input and output paths
# ------------------------------------------------------------

processed_dir <- file.path(project_root, "01_Data", "Processed")
objects_dir <- file.path(project_root, "03_Results", "Objects")
tables_dir <- file.path(project_root, "03_Results", "Tables")

dir.create(objects_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(tables_dir, recursive = TRUE, showWarnings = FALSE)

population_file <- file.path(
