  "population_control_stress_robust_z.rds"
)

if (!file.exists(population_file)) {
  stop(
    "Required input file not found:\n",
    population_file,
    "\nRun 011_Project_Control_Stress.R before this script."
  )
}

results_object_output <- file.path(
  objects_dir,
  "objective2_correlation_structure_permutation_robust.rds"
)

permutation_distribution_output <- file.path(
  objects_dir,
  "objective2_correlation_structure_permutation_distribution_robust.rds"
)

workbook_output <- file.path(
  tables_dir,
  "Objective2_Correlation_Structure_Permutation.xlsx"
)

global_csv_output <- file.path(
  tables_dir,
  "Objective2_Correlation_Structure_Global_Permutation.csv"
)

pairwise_csv_output <- file.path(
  tables_dir,
  "Objective2_Correlation_Structure_Pairwise_Differences.csv"
)

correlations_csv_output <- file.path(
