  "objective2_correlation_structure_permutation_sessionInfo.txt"
)

# ------------------------------------------------------------
# 4. Helper functions
# ------------------------------------------------------------

count_unique_by_column <- function(x) {
  x <- as.matrix(x)
  counts <- vapply(
    seq_len(ncol(x)),
    function(j) length(unique(x[, j])),
    integer(1)
  )
  names(counts) <- colnames(x)
  counts
}

standardised_midrank_matrix <- function(x, context) {
  x <- as.matrix(x)
  storage.mode(x) <- "double"

  if (nrow(x) < 3L || ncol(x) < 2L || any(!is.finite(x))) {
    stop(context, ": invalid matrix supplied to rank transformation.")
  }

  result <- matrix(
    NA_real_,
    nrow = nrow(x),
    ncol = ncol(x),
    dimnames = dimnames(x)
  )

  for (j in seq_len(ncol(x))) {
    ranks_j <- rank(x[, j], ties.method = "average")
    sd_j <- stats::sd(ranks_j)

    if (!is.finite(sd_j) || sd_j <= 0) {
      stop(context, ": non-positive rank-score SD for ", colnames(x)[j], ".")
    }

    result[, j] <- (ranks_j - mean(ranks_j)) / sd_j
  }

  if (!identical(dim(result), dim(x)) || any(!is.finite(result))) {
    stop(context, ": invalid standardised midrank matrix generated.")
  }

  result
}

validate_correlation_matrix <- function(x, context) {
  x <- as.matrix(x)
  expected_dim <- c(length(robust_variables), length(robust_variables))

  if (!identical(dim(x), expected_dim)) {
    stop(context, ": incorrect matrix dimensions.")
  }

  if (
    !identical(rownames(x), robust_variables) ||
    !identical(colnames(x), robust_variables)
  ) {
    stop(context, ": incorrect variable names or order.")
  }

  if (any(!is.finite(x))) {
    stop(context, ": non-finite correlation value detected.")
  }

  if (max(abs(x - t(x))) > numeric_tolerance) {
    stop(context, ": matrix is not symmetric.")
  }

  if (max(abs(diag(x) - 1)) > numeric_tolerance) {
    stop(context, ": diagonal is not equal to one.")
  }

  if (any(x < -1 - numeric_tolerance) || any(x > 1 + numeric_tolerance)) {
    stop(context, ": a correlation lies outside [-1, 1].")
  }

  invisible(TRUE)
}

matrix_to_long <- function(x, matrix_name, quantity_name) {
  x <- as.matrix(x)

  if (
    !identical(dim(x), c(4L, 4L)) ||
    !identical(rownames(x), robust_variables) ||
    !identical(colnames(x), robust_variables)
  ) {
    stop(matrix_name, ": invalid matrix supplied for long-format export.")
  }

  grid <- expand.grid(
    Row = seq_len(nrow(x)),
    Column = seq_len(ncol(x)),
    KEEP.OUT.ATTRS = FALSE,
    stringsAsFactors = FALSE
  )

  data.frame(
    Matrix = matrix_name,
    Quantity = quantity_name,
    Variable_1 = behavioural_variables[grid$Row],
    Variable_1_label = unname(variable_labels[behavioural_variables[grid$Row]]),
    Variable_2 = behavioural_variables[grid$Column],
    Variable_2_label = unname(variable_labels[behavioural_variables[grid$Column]]),
    Value = x[cbind(grid$Row, grid$Column)],
    stringsAsFactors = FALSE,
    check.names = FALSE
  )
}

matrix_to_export_table <- function(x) {
  output <- data.frame(
    Variable = rownames(x),
    as.data.frame(x, check.names = FALSE),
    stringsAsFactors = FALSE,
    check.names = FALSE
  )
  rownames(output) <- NULL
  output
}

# ------------------------------------------------------------
# 5. Load and validate the definitive corrected population
# ------------------------------------------------------------

population <- readRDS(population_file)

if (!is.data.frame(population)) {
  stop(basename(population_file), " does not contain a data frame.")
}

required_columns <- c(
  "Author",
  "ID",
  "Treatment",
  robust_variables
)

missing_columns <- setdiff(
  required_columns,
  names(population)
)

if (length(missing_columns) > 0L) {
  stop(
    "The corrected Objective 2 population object is missing:\n",
    paste(missing_columns, collapse = ", ")
  )
}

non_numeric_variables <- robust_variables[
  !vapply(
    population[, robust_variables, drop = FALSE],
    is.numeric,
    logical(1)
  )
]

if (length(non_numeric_variables) > 0L) {
  stop(
    "The following robust behavioural variables are not numeric:\n",
    paste(non_numeric_variables, collapse = ", ")
  )
}

population$Author <- trimws(
  as.character(population$Author)
)

population$ID <- trimws(
  as.character(population$ID)
)

population$Treatment <- factor(
  as.character(population$Treatment),
  levels = required_treatments
)

population$Traceability_ID <- paste(
  population$Author,
  population$ID,
  sep = " || "
)

if (
  anyNA(
    population[
      c(
        "Author",
        "ID",
        "Treatment",
        "Traceability_ID"
      )
    ]
  ) ||
  any(population$Author == "") ||
  any(population$ID == "") ||
  any(population$Traceability_ID == "")
) {
  stop(
    "Missing or empty Author + ID traceability values were detected."
  )
}

if (
  anyDuplicated(
    population$Traceability_ID
  ) > 0L
) {
  stop(
    "The corrected population does not contain unique Author + ID keys."
  )
}

if (
  length(
    unique(
      population$Author
    )
  ) != expected_number_of_authors
) {
  stop(
    "The corrected population does not contain the expected four Authors."
  )
}

if (anyNA(population$Treatment)) {
  stop("Treatment contains missing or unexpected values.")
}

control_rows <- population$Treatment == "Control"
stress_rows <- population$Treatment == "Stress"

control_n <- sum(control_rows)
stress_n <- sum(stress_rows)

if (
  control_n != expected_control_n ||
  stress_n != expected_stress_n
) {
  stop(
    "Unexpected group counts. Observed Control = ",
    control_n,
    "; Stress = ",
    stress_n,
    ". Expected 89 in each group."
  )
}

group_counts <- data.frame(
  Treatment = required_treatments,
  n = c(
    control_n,
    stress_n
  ),
  stringsAsFactors = FALSE
)

author_treatment_counts <- as.data.frame(
  table(
    Author = population$Author,
    Treatment = population$Treatment
  ),
  stringsAsFactors = FALSE
)

names(author_treatment_counts)[
  names(author_treatment_counts) == "Freq"
] <- "n"

if (
  nrow(author_treatment_counts) !=
    expected_number_of_authors *
      length(required_treatments) ||
  any(author_treatment_counts$n <= 0L) ||
  sum(author_treatment_counts$n) !=
    expected_control_n +
      expected_stress_n
) {
  stop(
    "The Author-by-Treatment count audit is invalid."
  )
}

behaviour_matrix <- as.matrix(
  population[, robust_variables, drop = FALSE]
)

storage.mode(behaviour_matrix) <- "double"
colnames(behaviour_matrix) <- robust_variables
rownames(behaviour_matrix) <- population$Traceability_ID

if (!identical(dim(behaviour_matrix), c(178L, 4L))) {
  stop("The corrected behavioural matrix must have dimensions 178 x 4.")
}

if (any(!is.finite(behaviour_matrix))) {
  stop("Missing or non-finite values detected in the behavioural matrix.")
}

control_matrix <- behaviour_matrix[
  control_rows,
  ,
  drop = FALSE
]

stress_matrix <- behaviour_matrix[
  stress_rows,
  ,
  drop = FALSE
]

if (
  !identical(
    dim(control_matrix),
    c(expected_control_n, 4L)
  ) ||
  !identical(
    dim(stress_matrix),
    c(expected_stress_n, 4L)
  )
) {
  stop("The Control or Stress matrix has incorrect dimensions.")
}

control_unique <- count_unique_by_column(control_matrix)
stress_unique <- count_unique_by_column(stress_matrix)

if (
  length(control_unique) != 4L ||
  length(stress_unique) != 4L
) {
  stop("Unique-value counting did not return one value per variable.")
}

if (
  any(control_unique < 2L) ||
  any(stress_unique < 2L)
) {
  stop("At least one behavioural variable is constant within a group.")
}

unique_value_counts <- data.frame(
  Variable = robust_variables,
  Control_unique_values =
    as.integer(
      control_unique[
        robust_variables
      ]
    ),
  Stress_unique_values =
    as.integer(
      stress_unique[
        robust_variables
      ]
    ),
  stringsAsFactors = FALSE
)

# Audit the already-completed robust normalisation separately within
# each Author. This script does not recalculate or modify the robust
# coordinates used in the correlation analysis.

normalisation_audit <- do.call(
  rbind,
  lapply(
    sort(
      unique(
        population$Author
      )
    ),
    function(author_i) {

      author_control_matrix <- as.matrix(
        population[
          population$Author == author_i &
            population$Treatment == "Control",
          robust_variables,
          drop = FALSE
        ]
      )

      storage.mode(
        author_control_matrix
      ) <- "double"

      if (
        nrow(author_control_matrix) == 0L ||
        any(!is.finite(author_control_matrix))
      ) {
        stop(
          "Invalid Control reference data were detected for Author ",
          author_i,
          "."
        )
      }

      data.frame(
        Author = author_i,
        Robust_variable = robust_variables,
        Control_median = as.numeric(
          apply(
            author_control_matrix,
            2,
            stats::median
          )
        ),
        Control_scaled_MAD = as.numeric(
          apply(
            author_control_matrix,
            2,
            stats::mad,
            constant = 1.4826
          )
        ),
        stringsAsFactors = FALSE
      )
    }
  )
)

rownames(normalisation_audit) <- NULL

if (
  nrow(normalisation_audit) !=
    expected_number_of_authors *
      length(robust_variables) ||
  any(
    !is.finite(
      normalisation_audit$Control_median
    )
  ) ||
  any(
    !is.finite(
      normalisation_audit$Control_scaled_MAD
    )
  )
) {
  stop(
    "The Author-specific robust-normalisation audit is invalid."
  )
}

if (
  any(
    abs(
      normalisation_audit$Control_median
    ) > numeric_tolerance
  )
) {
  stop(
    "At least one Author-specific Control median is not zero ",
    "within tolerance."
  )
}

if (
  any(
    abs(
      normalisation_audit$Control_scaled_MAD -
        1
    ) > numeric_tolerance
  )
) {
  stop(
    "At least one Author-specific Control scaled MAD is not one ",
    "within tolerance."
  )
}

# ------------------------------------------------------------
# 6. Observed Spearman correlation structures
# ------------------------------------------------------------

cor_control <- stats::cor(
  control_matrix,
  method = "spearman",
  use = "everything"
)

cor_stress <- stats::cor(
  stress_matrix,
  method = "spearman",
  use = "everything"
)

validate_correlation_matrix(cor_control, "Control Spearman matrix")
validate_correlation_matrix(cor_stress, "Stress Spearman matrix")

control_rank_scores <- standardised_midrank_matrix(
  control_matrix,
  "Control"
)

stress_rank_scores <- standardised_midrank_matrix(
  stress_matrix,
  "Stress"
)

cor_control_rank <- stats::cor(
  control_rank_scores,
  method = "pearson",
  use = "everything"
)

cor_stress_rank <- stats::cor(
  stress_rank_scores,
  method = "pearson",
  use = "everything"
)

if (!isTRUE(all.equal(
  unname(cor_control),
  unname(cor_control_rank),
  tolerance = 1e-12,
  check.attributes = FALSE
))) {
  stop("Control rank scores do not reproduce the Spearman matrix.")
}

if (!isTRUE(all.equal(
  unname(cor_stress),
  unname(cor_stress_rank),
  tolerance = 1e-12,
  check.attributes = FALSE
))) {
  stop("Stress rank scores do not reproduce the Spearman matrix.")
}

# ------------------------------------------------------------
# 7. Observed global and pairwise differences
# ------------------------------------------------------------

upper_index <- which(upper.tri(cor_control, diag = FALSE), arr.ind = TRUE)

if (!identical(dim(upper_index), c(6L, 2L))) {
  stop("Four variables must produce six unique off-diagonal pairs.")
}

difference_matrix <- cor_stress - cor_control
observed_delta <- as.numeric(difference_matrix[upper_index])

if (length(observed_delta) != 6L || any(!is.finite(observed_delta))) {
  stop("The observed pairwise correlation differences are invalid.")
}

observed_l2 <- sqrt(sum(observed_delta^2))
observed_frobenius <- sqrt(2) * observed_l2
observed_rms <- sqrt(mean(observed_delta^2))
observed_max_abs <- max(abs(observed_delta))

row_index <- upper_index[, 1]
column_index <- upper_index[, 2]

pair_ids <- paste0(
  behavioural_variables[row_index],
  "__",
  behavioural_variables[column_index]
)

if (length(pair_ids) != 6L || anyDuplicated(pair_ids) > 0L) {
  stop("The six behavioural-pair identifiers are invalid.")
}

pairwise_observed <- data.frame(
  Pair_ID = pair_ids,
  Variable_1 = behavioural_variables[row_index],
  Variable_1_label = unname(variable_labels[behavioural_variables[row_index]]),
  Variable_2 = behavioural_variables[column_index],
  Variable_2_label = unname(variable_labels[behavioural_variables[column_index]]),
  Control_Spearman_rho = as.numeric(cor_control[upper_index]),
  Stress_Spearman_rho = as.numeric(cor_stress[upper_index]),
  Delta_rho_Stress_minus_Control = observed_delta,
  Absolute_Delta_rho = abs(observed_delta),
  stringsAsFactors = FALSE,
  check.names = FALSE
)

if (
  nrow(pairwise_observed) != 6L ||
  any(!is.finite(pairwise_observed$Delta_rho_Stress_minus_Control))
) {
  stop("The observed pairwise-correlation table is invalid.")
}

# ------------------------------------------------------------
# 8. Marginally aligned permutation test
# ------------------------------------------------------------

pooled_rank_scores <- rbind(control_rank_scores, stress_rank_scores)

if (!identical(dim(pooled_rank_scores), c(178L, 4L))) {
  stop("The pooled rank-score matrix must have dimensions 178 x 4.")
}

permutation_l2 <- numeric(n_permutations)
permutation_rms <- numeric(n_permutations)
permutation_max_abs <- numeric(n_permutations)
permutation_pairwise <- matrix(
  NA_real_,
  nrow = n_permutations,
  ncol = 6L,
  dimnames = list(NULL, pair_ids)
)

set.seed(permutation_seed)

for (b in seq_len(n_permutations)) {
  shuffled <- sample.int(178L, size = 178L, replace = FALSE)
  control_indices_b <- shuffled[seq_len(expected_control_n)]
  stress_indices_b <- shuffled[expected_control_n + seq_len(expected_stress_n)]

  control_b <- pooled_rank_scores[control_indices_b, , drop = FALSE]
  stress_b <- pooled_rank_scores[stress_indices_b, , drop = FALSE]

  cor_control_b <- stats::cor(control_b, method = "pearson", use = "everything")
  cor_stress_b <- stats::cor(stress_b, method = "pearson", use = "everything")

  delta_b <- as.numeric((cor_stress_b - cor_control_b)[upper_index])

  if (length(delta_b) != 6L || any(!is.finite(delta_b))) {
    stop("Permutation ", b, " produced invalid correlation differences.")
  }

  permutation_pairwise[b, ] <- delta_b
  permutation_l2[b] <- sqrt(sum(delta_b^2))
  permutation_rms[b] <- sqrt(mean(delta_b^2))
  permutation_max_abs[b] <- max(abs(delta_b))
}

if (
  any(!is.finite(permutation_l2)) ||
  any(!is.finite(permutation_rms)) ||
  any(!is.finite(permutation_max_abs)) ||
  any(!is.finite(permutation_pairwise))
) {
  stop("The permutation procedure produced non-finite statistics.")
}

comparison_tolerance <- sqrt(.Machine$double.eps)

global_p <- (
  1 + sum(permutation_l2 >= observed_l2 - comparison_tolerance)
) / (n_permutations + 1)

raw_pairwise_p <- vapply(
  seq_len(6L),
  function(j) {
    (
      1 + sum(
        abs(permutation_pairwise[, j]) >=
          abs(observed_delta[j]) - comparison_tolerance
      )
    ) / (n_permutations + 1)
  },
  numeric(1)
)

maxT_pairwise_p <- vapply(
  seq_len(6L),
  function(j) {
    (
      1 + sum(
        permutation_max_abs >=
          abs(observed_delta[j]) - comparison_tolerance
      )
    ) / (n_permutations + 1)
  },
  numeric(1)
)

holm_pairwise_p <- stats::p.adjust(raw_pairwise_p, method = "holm")
fdr_pairwise_p <- stats::p.adjust(raw_pairwise_p, method = "BH")

if (
  any(raw_pairwise_p < 0 | raw_pairwise_p > 1) ||
  any(maxT_pairwise_p < 0 | maxT_pairwise_p > 1) ||
  any(maxT_pairwise_p + comparison_tolerance < raw_pairwise_p)
) {
  stop("The pairwise permutation p-values are invalid.")
}

pairwise_original_order <- pairwise_observed
pairwise_original_order$Raw_two_sided_permutation_p <- raw_pairwise_p
pairwise_original_order$MaxT_FWER_adjusted_p <- maxT_pairwise_p
pairwise_original_order$Holm_adjusted_p <- holm_pairwise_p
pairwise_original_order$FDR_adjusted_p <- fdr_pairwise_p

pairwise_results <- pairwise_original_order[
  order(pairwise_original_order$Absolute_Delta_rho, decreasing = TRUE),
  ,
  drop = FALSE
]
rownames(pairwise_results) <- NULL

if (
  nrow(pairwise_results) != 6L ||
  anyDuplicated(pairwise_results$Pair_ID) > 0L ||
  !identical(pairwise_original_order$Pair_ID, pair_ids)
) {
  stop("The final pairwise-results tables are invalid.")
}

# ------------------------------------------------------------
# 9. Result tables
# ------------------------------------------------------------

global_result <- data.frame(
  Comparison = "Stress versus Control",
  Design = "Two independent populations",
  Correlation = "Spearman",
  Null_construction = paste0(
    "Unrestricted label permutation of pooled centred and ",
    "standardised within-group midrank scores"
  ),
  Number_of_variables = 4L,
  Number_of_unique_correlations = 6L,
  Control_n = control_n,
  Stress_n = stress_n,
  Observed_unique_edge_L2 = observed_l2,
  Observed_full_Frobenius = observed_frobenius,
  Observed_RMS_delta_rho = observed_rms,
  Observed_max_absolute_delta_rho = observed_max_abs,
  Global_permutation_p = global_p,
  Permutations = n_permutations,
  Seed = permutation_seed,
  Minimum_attainable_p = 1 / (n_permutations + 1),
  Monte_Carlo_SE_at_observed_p = sqrt(
    global_p * (1 - global_p) / (n_permutations + 1)
  ),
  stringsAsFactors = FALSE,
  check.names = FALSE
)

permutation_frobenius <- sqrt(2) * permutation_l2

permutation_summary <- data.frame(
  Statistic = c(
    "Unique-edge L2 norm",
    "Full Frobenius norm",
    "RMS delta rho",
    "Maximum absolute delta rho"
  ),
  Observed = c(
    observed_l2,
    observed_frobenius,
    observed_rms,
    observed_max_abs
  ),
  Null_mean = c(
    mean(permutation_l2),
    mean(permutation_frobenius),
    mean(permutation_rms),
    mean(permutation_max_abs)
  ),
  Null_SD = c(
    stats::sd(permutation_l2),
    stats::sd(permutation_frobenius),
    stats::sd(permutation_rms),
    stats::sd(permutation_max_abs)
  ),
  Null_median = c(
    stats::median(permutation_l2),
    stats::median(permutation_frobenius),
    stats::median(permutation_rms),
    stats::median(permutation_max_abs)
  ),
  Null_Q95 = c(
    as.numeric(stats::quantile(permutation_l2, 0.95, names = FALSE)),
    as.numeric(stats::quantile(permutation_frobenius, 0.95, names = FALSE)),
    as.numeric(stats::quantile(permutation_rms, 0.95, names = FALSE)),
    as.numeric(stats::quantile(permutation_max_abs, 0.95, names = FALSE))
  ),
  Null_Q99 = c(
    as.numeric(stats::quantile(permutation_l2, 0.99, names = FALSE)),
    as.numeric(stats::quantile(permutation_frobenius, 0.99, names = FALSE)),
    as.numeric(stats::quantile(permutation_rms, 0.99, names = FALSE)),
    as.numeric(stats::quantile(permutation_max_abs, 0.99, names = FALSE))
  ),
  stringsAsFactors = FALSE
)

correlation_long <- rbind(
  matrix_to_long(cor_control, "Control", "Spearman rho"),
  matrix_to_long(cor_stress, "Stress", "Spearman rho"),
  matrix_to_long(difference_matrix, "Stress minus Control", "Delta rho")
)
rownames(correlation_long) <- NULL

if (nrow(correlation_long) != 48L || any(!is.finite(correlation_long$Value))) {
  stop("The long-format correlation table is invalid.")
}

control_matrix_table <- matrix_to_export_table(cor_control)
stress_matrix_table <- matrix_to_export_table(cor_stress)
difference_matrix_table <- matrix_to_export_table(difference_matrix)

