  Variable = behavioural_variables,
  Variable_label = unname(variable_labels[behavioural_variables]),
  Robust_variable = robust_variables,
  Control_n = control_n,
  Control_unique_values = as.integer(control_unique[robust_variables]),
  Control_repeated_observations = control_n - as.integer(control_unique[robust_variables]),
  Stress_n = stress_n,
  Stress_unique_values = as.integer(stress_unique[robust_variables]),
  Stress_repeated_observations = stress_n - as.integer(stress_unique[robust_variables]),
  stringsAsFactors = FALSE
)

# ------------------------------------------------------------
# 10. Save definitive outputs
# ------------------------------------------------------------

permutation_distribution <- list(
  Replicate = seq_len(n_permutations),
  Unique_edge_L2 = permutation_l2,
  Full_Frobenius = permutation_frobenius,
  RMS_delta_rho = permutation_rms,
  Maximum_absolute_delta_rho = permutation_max_abs,
  Pairwise_delta_rho = permutation_pairwise,
  Pair_ID_original_order = pair_ids
)

if (!identical(colnames(permutation_pairwise), pair_ids)) {
  stop("The pairwise permutation matrix is not aligned with pair IDs.")
}

